edits.after:
error = ext4_xattr_ibody_find(inode, &i, &is);
if (error)
	goto out;

if (is.s.not_found) {
	if (is.s.not_found == -ENODATA)
		EXT4_ERROR_INODE(inode, "inline data xattr not found");
	else
		EXT4_ERROR_INODE(inode, "error %d probing inline data xattr",
				 is.s.not_found);
	error = -EFSCORRUPTED;
	goto out;
}

